mapper.select:
select t0.*, ifnull(t1.总房间数, 0) totalRoomCount, ifnull(t1.总房间数, 0) - ifnull(t2.在租房间数, 0) freeRoomCount, (select gi.url from graph_info gi where gi.item_type = 1 and gi.item_id = t0.id and gi.is_deleted = 0 order by gi.id asc limit 1) cover from (select * from apartment_info where is_deleted = 0
and province_id = #{queryVo.provinceId}
and city_id = #{queryVo.cityId}
and district_id = #{queryVo.districtId}
and name like concat('%', #{queryVo.name}, '%') ) t0 left join (select apartment_id, count(*) 总房间数 from room_info where is_deleted = 0 group by apartment_id) t1 on t0.id = t1.apartment_id left join (select apartment_id, count(*) 在租房间数 from lease_agreement where is_deleted = 0 and `status` in (2, 5, 7) group by apartment_id) t2 on t0.id = t2.apartment_id order by t0.id desc
